import * as React from "react";
import { graphql, PageProps } from "gatsby";
import data from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import Palette from "../components/palette";
import Navigation from "../components/nav";
import Icon from "../components/icon";
import Logo from "../components/logo";
import ContactForm from "../components/contactForm";
import Carousel from "../components/carousel";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const currentYear = new Date().getFullYear();
  const { t } = useTranslation();
  const statements = t("heroBanner.statements", {
    returnObjects: true,
  }) as string[];
  const ourPurposeContent = t("ourPurpose.content", {
    returnObjects: true,
  }) as string[];
  return (
    <section className="bg-MidGray">
      <Navigation />

      {/* <Palette/> */}
      <section
        className={`${styles.container} bg-DarkGreen relative h-full pb-16`}
        id={"start"}
        style={{
          backgroundImage: `url(${images.hero_image.src})`,
          backgroundSize: "100% auto", // fuerza el ancho al 100% del viewport
          backgroundRepeat: "no-repeat",
          backgroundPosition: "bottom center",
        }}
      >
        {/* Gradient overlay */}
        <div className="absolute bottom-[15%] left-0 right-0 h-[85%] bg-gradient-to-b from-transparent to-DarkGreen opacity-100 pointer-events-none z-10" />
        {/* Frame oscuro sólido del 15% inferior */}
        <div className="absolute bottom-0 left-0 right-0 h-[15%] bg-DarkGreen pointer-events-none z-10" />

        <article className="relative z-20 flex flex-col items-center w-full h-full px-0">
          <div className="max-w-[1720px] w-full mb-[7%] mt-[25%] flex">
            <div className="w-[120px]">
              <Icon fill="Yellow" />
            </div>
          </div>
          <div className="max-w-[1720px] w-full flex flex-col sm:flex-row items-center justify-between">

            <div>
              <Logo  />
              <h2 className="text-white uppercase subheader mt-[10%]">
                {t("heroBanner.subtitle")}
              </h2>
            </div>

            <div className="flex flex-wrap flex-col mt-4">
              {statements.map((item: string, index: number) => (
                <p key={index} className={`${index === 0 && "text-white"} text-Yellow uppercase header mb-4`}>
                  {item}
                </p>
              ))}
            </div>

          </div>
        </article>
      </section>

      <section className={`${styles.container} bg-DarkGreen`} id={userData.menu[0]}>
        <article className="relative z-20 flex flex-col items-center w-full h-full px-0 ">

          <div className="max-w-[1720px] w-full flex flex-col sm:flex-row items-center justify-between">
            <div className="flex flex-wrap flex-col w-full bg-green">
              <h3 className="text-LightGrayText uppercase subheader mt-[10%] mb-[30%]">
                {t("ourPurpose.title")}
              </h3>
              {(t("ourPurpose.content", { returnObjects: true }) as { item: string }[]).map(
                (item: { item: string }, index: number) => (
                  <p
                    key={index}
                    className={`text-MidGray large-text mb-8`}
                  >
                    {item.item}
                  </p>
                )
              )}
            </div>
            <div className="hidden sm:flex w-full">
              <div className="opacity-40 w-full ml-[30%]">
                <Icon fill="black" />
              </div>
            </div>

          </div>
        </article>
      </section>

      <section className={`${styles.container} bg-gradient-to-b from-DarkGreen to-transparent opacity-100 pt-28`} id={userData.menu[1]}>
        <h3 className="subheader text-LightGrayText uppercase mb-8">{t("carousel.title")}</h3>
        <Carousel />
      </section>

      <section className={styles.container} id={userData.menu[2]}>
        <div className="h-96 bg-Yellow">
          <h2 className="text-4xl">{userData.menu[2]}</h2>
        </div>
      </section>
      <section className={styles.container} id={userData.menu[3]}>
        <div className="h-96 bg-DarkGreen">
          <h2 className="text-4xl">{userData.menu[3]}</h2>
        </div>
      </section>
      <section className={styles.container} id={userData.menu[4]}>
        <div className="h-96 bg-Yellow">
          <h2 className="text-4xl">{userData.menu[4]}</h2>
          <ContactForm />
        </div>
      </section>
      <footer className={styles.footerContainer}>
        <div className="flex flex-col sm:flex-row min-h-24 sm:min-h-96 w-full">
          <div className="flex flex-col py-2 sm:py-8 mx-auto sm:ml-0 justify-end">
            <Logo />
          </div>

          <div className="flex flex-col w-full justify-end">
            <div
              className={`justify-end py-6 px-4 text-[12px] text-center sm:text-end`}
            >
              &copy; {currentYear} {data?.name}
            </div>
          </div>
        </div>
      </footer>
    </section>
  );
};

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full px-5 sm:px-16",
  section:
    "flex h-96 bg-primary my-8 w-full border border-primary rounded-lg shadow-md",
  title: "head-3 sm:head-1 text-Tofu",
  footerContainer: "flex flex-col text-light w-full px-7 ",
};
